def max_product_with_one_increment(n, digits):
    product = 1
    for digit in digits:
        product *= digit

    max_product = 0
    for i in range(n):
        if digits[i] == 0:
            continue
        new_product = product // digits[i] * (digits[i] + 1)
        if new_product > max_product:
            max_product = new_product

    return max_product

t = int(input())
for _ in range(t):
