    digits = list(map(int, input().split()))
    print(max_product_with_one_increment(n, digits))

def min_operations_to_divisible(n, k, a):
    product = 1
    for num in a:
        product *= num

    if product % k == 0:
        return 0

    count = 0
    for num in a:
        if num > k // 2:
            count += 1

    return count

