def max_alternating_sum(n, a):
    max_even = float('-inf')
    max_odd = float('-inf')

    for i in range(n):
        if a[i] % 2 == 0:
            max_even = max(a[i], max_odd + a[i])
        else:
            max_odd = max(a[i], max_even + a[i])

    return max(max_even, max_odd)

