def minExtraChar(s, dictionary):
    dp = [float('inf')] * (len(s) + 1)
    dp[0] = 0
    for i in range(1, len(s) + 1):
        for j in range(i):
            if s[j:i] in dictionary:
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[-1]

def count_good_integers(num1, num2, min_sum, max_sum):
    MOD = 10**9 + 7
    dp = [[0] * (max_sum + 1) for _ in range(len(num2) + 1)]
    dp[0][0] = 1
    for i in range(1, len(num2) + 1):
        for j in range(min_sum, max_sum + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i - 1][j - 1]
            if j < max_sum:
                dp[i][j] += dp[i - 1][j + 1]
            dp[i][j] %= MOD
    return dp[len(num2)][max_sum]

def min_length(s: str) -> int:
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i:j+1] == "AB" or s[i:j+1] == "CD":
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = min(dp[i][j-1], dp[i+1][j])

    return min(dp[i][n-1] for i in range(n))

def make_palindrome(s: str) -> str:
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            if s[left] < s[right]:
                s = s[:left] + s[right] + s[left+1:]
            else:
                s = s[:right] + s[left] + s[right+1:]
        left += 1
        right -= 1
    return s

def is_fascinating(n):
    concatenated = str(n) + str(2 * n) + str(3 * n)
    if len(concatenated) != 9:
        return False
    if '0' in concatenated:
        return False
    if sorted(concatenated) != list(range(1, 10)):
        return False
    return True

