def canTraverseAllPairs(nums):
    graph = {}
    for i, num in enumerate(nums):
        if num not in graph:
            graph[num] = []
        for j, gcd_value in enumerate(nums[i+1:], i+1):
            if gcd_value > 1:
                graph[num].append(j)

    def dfs(node, visited):
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if not dfs(neighbor, visited):
                return False
        return True

    visited = set()
    return dfs(0, visited)

def specialPermutation(nums):
    MOD = 10**9 + 7
    memo = {}

    def dp(i, last):
        if i == len(nums):
            return 1
        if (i, last) in memo:
            return memo[(i, last)]
        if nums[i] % nums[i+1] == 0:
            result = dp(i+1, last)
        else:
            result = dp(i+1, last) + dp(i+1, nums[i])
        memo[(i, last)] = result
        return result

    return dp(0, -1)

def count_good_splits(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * n
    dp[0] = 1  # Base case: one way to split the first element

    for i in range(1, n):
        if nums[i] == 1:
            dp[i] = dp[i - 1]
        else:
            dp[i] = (dp[i - 1] + dp[i - 2]) % MOD

    return dp[-1]

