    low_int = int(low)
    high_int = int(high)

    def count_stepping_numbers_helper(num_str, low_int, high_int):
        if num_str == "":
            return 1 if low_int <= int(num_str) <= high_int else 0

        if num_str[0] == '0':
            return 0

        count = 0
        for digit in range(int(num_str[0]) - 1, int(num_str[0]) + 2):
            if int(num_str[1]) == digit - 1 or int(num_str[1]) == digit + 1:
                count += count_stepping_numbers_helper(num_str[1:], low_int, high_int)

        return count % MOD

