def smallest_missing_integer(nums):
    longest_sequential_prefix_sum = 0
    for i in range(len(nums)):
        if i == 0:
            longest_sequential_prefix_sum += nums[i]
        else:
            if nums[i] == nums[i - 1] + 1:
                longest_sequential_prefix_sum += nums[i]
            else:
                break
    for i in range(len(nums) + 1):
        if i >= longest_sequential_prefix_sum and i not in nums:
            return i

def min_operations(x, y):
    operations = 0
    while x != y:
        if x % 11 == 0:
            x //= 11
        elif x % 5 == 0:
            x //= 5
        elif x > y:
            x -= 1
        else:
            y -= 1
        operations += 1
    return operations

