def longest_special_substring(s: str) -> int:
    max_length = -1
    count = {}
    left = 0
    for right in range(len(s)):
        if s[right] not in count:
            count[s[right]] = 0
        count[s[right]] += 1
        while count[s[right]] > 1:
            count[s[left]] -= 1
            if count[s[left]] == 0:
                del count[s[left]]
            left += 1
        if count[s[right]] == 3:
            max_length = max(max_length, right - left + 1)
    return max_length

