def bfs(grid, start, goal, T):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(start, 0, 0)])  # (current position, moves, candy squares visited)
    visited = set()
    visited.add(start)

    while queue:
        (i, j), moves, candy_squares = queue.popleft()

        if (i, j) == goal:
            return candy_squares

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#':
                if (ni, nj) not in visited:
                    visited.add((ni, nj))
                    queue.append(((ni, nj), moves + 1, candy_squares))

    return -1

