def calculate_sleep_time(N, A, Q, queries):
    sleep_times = []
    for i in range(Q):
        l, r = queries[i]
        start = A[2 * i]
        end = A[2 * i + 1]
        if start > r:
            sleep_times.append(0)
        elif end < l:
            sleep_times.append(0)
        else:
            sleep_times.append(end - start)
    return sleep_times

