from collections import deque

def bfs(graph, start, h):
    distances = {vertex: float('inf') for vertex in graph}
    distances[start] = 0
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if distances[neighbor] == float('inf'):
                distances[neighbor] = distances[current] + 1
                queue.append(neighbor)
    return distances

def find_guarded_vertices(N, M, K, edges, guards):
    graph = {i: [] for i in range(1, N + 1)}
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    distances = {}
    for guard, h in zip(guards, range(1, K + 1)):
        distances[guard] = bfs(graph, guard, h)

    guarded_vertices = set()
    for vertex in range(1, N + 1):
        if distances[vertex] <= 1:
            guarded_vertices.add(vertex)

    return len(guarded_vertices), sorted(guarded_vertices)

