from collections import deque

def is_valid(i, j, H, W, visited):
    return 0 <= i < H and 0 <= j < W and not visited[i][j]

def bfs(H, W, S):
    visited = [[False] * W for _ in range(H)]
    queue = deque([(0, 0)])
    visited[0][0] = True

    while queue:
        i, j = queue.popleft()
        if i == H - 1 and j == W - 1:
            return True

        if i > 0 and not visited[i - 1][j]:
            queue.append((i - 1, j))
            visited[i - 1][j] = True
        if j > 0 and not visited[i][j - 1]:
            queue.append((i, j - 1))
            visited[i][j - 1] = True

        if i + 1 < H and not visited[i + 1][j]:
            queue.append((i + 1, j))
            visited[i + 1][j] = True
        if j + 1 < W and not visited[i][j + 1]:
            queue.append((i, j + 1))
            visited[i][j + 1] = True

    return False

