from collections import deque

def bfs_shortest_path(graph, start, end):
    queue = deque([(start, 0)])
    visited = set()
    while queue:
        node, dist = queue.popleft()
        if node == end:
            return dist
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, dist + 1))
    return float('inf')

def bfs_longest_shortest_path(graph, start, end):
    queue = deque([(start, 0)])
    visited = set()
    longest_dist = 0
    while queue:
        node, dist = queue.popleft()
        if node == end:
            longest_dist = dist
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, dist + 1))
    return longest_dist

