def find_cycle(N, A):
    visited = [False] * (N + 1)
    parent = [None] * (N + 1)
    cycle = []

    def dfs(v):
        if visited[v]:
            return
        visited[v] = True
        parent[v] = v
        for u in range(1, N + 1):
            if A[v - 1] == u and not visited[u]:
                dfs(u)
                if parent[v] is not None:
                    cycle.append(parent[v])
                parent[v] = None
        return

    for i in range(1, N + 1):
        if not visited[i]:
            dfs(i)

    return cycle[1:]

