def mark_and_remove_cookies(H, W, grid):
    marked = set()

    # Mark cookies in each row
    for i in range(H):
        row = grid[i]
        for j in range(W):
            if len(set(row[j] for j in range(W))) > 1:
                marked.add((i, j))

    # Mark cookies in each column
    for j in range(W):
        col = [grid[i][j] for i in range(H)]
        for i in range(H):
            if len(set(col[i] for i in range(H))) > 1:
                marked.add((i, j))

    # Remove marked cookies
    for i, j in marked:
        grid[i][j] = '.'

    # Count remaining cookies
    return sum(row.count('.') for row in grid)

