def count_disappointing_sequences(grid):
    n = len(grid)
    dp = [[0] * n for _ in range(n)]

    # Initialize the first row
    for j in range(n):
        dp[0][j] = 1 if grid[0][j] != grid[0][j+1] else 0

    # Initialize the first column
    for i in range(1, n):
        dp[i][0] = 1 if grid[i][0] != grid[i-1][0] else 0

    # Fill the dp table
    for i in range(1, n):
        for j in range(1, n):
            if grid[i][j] == grid[i-1][j]:
                dp[i][j] = dp[i-1][j]
            elif grid[i][j] == grid[i][j-1]:
                dp[i][j] = dp[i][j-1]
            elif grid[i][j] == grid[i-1][j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1]

    return dp[-1][-1]

