def check_transformations(T, T_prime, S):
    if T_prime == T:
        return True
    if len(T_prime) == len(T) + 1:
        return T_prime == T + S[0]
    if len(T_prime) == len(T) - 1:
        return T_prime == T[:-1] + S[1:]
    if len(T_prime) == len(T) - 2:
        return T_prime == T[:-2] + S[1:] + S[0]
    return False

