def count_triples(N, grid):
    # Step 1: Identify the positions of 'o' in the grid
    positions = []
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'o':
                positions.append((i, j))

    # Step 2: Count the number of 'o' cells in the same row
    row_counts = {}
    for i, j in positions:
        if i not in row_counts:
            row_counts[i] = []
        row_counts[i].append(j)

    # Step 3: Count the number of 'o' cells in the same column
    col_counts = {}
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'o':
                col_counts.setdefault(j, []).append(i)

    # Step 4: Sum up the counts from step 2 and step 3
    total_triples = 0
    for i, j in positions:
        if i in row_counts and j in col_counts:
            total_triples += len(row_counts[i]) * len(col_counts[j])

    return total_triples

