def min_operations(H, W, A, B):
    if A == B:
        return 0

    # Check if the grids can be transformed into each other
    if sorted(A) != sorted(B):
        return -1

    # Count the number of swaps needed to transform grid A into grid B
    row_swaps = 0
    col_swaps = 0

    for i in range(H):
        for j in range(W):
            if A[i][j] != B[i][j]:
                if i < H - 1:
                    row_swaps += 1
                if j < W - 1:
                    col_swaps += 1

    # Count the number of swaps needed to transform grid B into grid A
    row_swaps = 0
    col_swaps = 0

    for i in range(H):
        for j in range(W):
            if B[i][j] != A[i][j]:
                if i < H - 1:
                    row_swaps += 1
                if j < W - 1:
                    col_swaps += 1

    # Calculate the total number of swaps
    total_swaps = row_swaps + col_swaps

    return total_swaps

