def takahashi_adventure(N, events):
    potions = [0] * (N + 1)
    min_potions = 0
    actions = []

    for i, (t, x) in enumerate(events):
        if t == 1:
            potions[x] += 1
            min_potions = min(min_potions, potions[x])
            actions.append(1 if potions[x] > 0 else 0)
        elif t == 2:
            if potions[x] > 0:
                potions[x] -= 1
                min_potions = min(min_potions, potions[x])
                actions.append(1 if potions[x] > 0 else 0)
            else:
                return -1
        else:
            return -1

    return min_potions, actions

