import heapq

def dijkstra(n, graph, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, weight in graph[u]:
            if dist[u] + weight < dist[v]:
                dist[v] = dist[u] + weight
                heapq.heappush(pq, (dist[v], v))
    return dist

def shortest_tour_length(n, m, x):
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n):
        graph[i].append((i + 1, 1))
    graph[n].append((1, 1))
    for i in range(1, n):
        for j in range(i + 1, n):
            graph[i].append((j, 1))
            graph[j].append((i, 1))
    dist = dijkstra(n, graph, 1)
    return dist[x]

def shortest_tour_length_with_bridge_closed(n, m, x):
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n):
        graph[i].append((i + 1, 1))
    graph[n].append((1, 1))
    for i in range(1, n):
        for j in range(i + 1, n):
            graph[i].append((j, 1))
            graph[j].append((i, 1))
    dist = dijkstra(n, graph, 1)
    for i in range(1, n):
        for j in range(i + 1, n):
            if dist[i] + dist[j] + 1 < dist[x]:
                dist[x] = dist[i] + dist[j] + 1
    return dist[x]

