def min_total_weight(N, M, edges):
    dp = [[float('inf')] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for u, v, w in edges:
                if u == j:
                    dp[i][j] = min(dp[i][j], dp[i - 1][u] + w)
                elif v == j:
                    dp[i][j] = min(dp[i][j], dp[i - 1][u] + w)
                else:
                    dp[i][j] = min(dp[i][j], dp[i - 1][u] + w)
    return dp[N][N] if dp[N][N] != float('inf') else -1

