def min_moves_to_same_cell(grid, player1_pos, player2_pos):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    min_moves = float('inf')

    for dx, dy in directions:
        x1, y1 = player1_pos
        x2, y2 = player2_pos

        if dx == 0 and dy == 0:
            continue

        x1 += dx
        y1 += dy
        x2 += dx
        y2 += dy

        if 0 <= x1 < N and 0 <= y1 < N and 0 <= x2 < N and 0 <= y2 < N:
            min_moves = min(min_moves, abs(x1 - x2) + abs(y1 - y2))

    return min_moves if min_moves != float('inf') else -1

