def find_different_position(s):
    # Count the occurrences of each character in the string
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the character that appears only once
    different_char = None
    for char, count in char_count.items():
        if count == 1:
            different_char = char
            break

    # Find the position of the different character
    different_position = s.index(different_char)

    return different_position

