def solve(N, A, M, B, L, C, Q, X):
    dp = [[False] * (L + 1) for _ in range(M + 1)]
    dp[0][0] = True

    for i in range(1, M + 1):
        for j in range(1, L + 1):
            if A[i - 1] <= j:
                dp[i][j] = dp[i - 1][j - A[i - 1]]
            if B[i - 1] <= j:
                dp[i][j] = dp[i - 1][j - B[i - 1]]
            if C[i - 1] <= j:
                dp[i][j] = dp[i - 1][j - C[i - 1]]

    results = []
    for x in X:
        found = False
        for i in range(1, M + 1):
            for j in range(1, L + 1):
                if dp[i][j]:
                    found = True
                    break
            if found:
                break
        results.append("Yes" if found else "No")

    return results

