class Node:
    def __init__(self, value):
        self.value = value
        self.next = None
        self.prev = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert_after(self, x, y):
        node = Node(y)
        node.next = x.next
        node.prev = x
        if x.next:
            x.next.prev = node
        x.next = node
        if node.next:
            node.next.next = node
        node.next = y
        if y.next:
            y.next.prev = node
        y.next = node
        self.size += 1

    def remove(self, x):
        if not self.head:
            return
        if self.head == x:
            self.head = self.head.next
            if self.head:
                self.head.prev = None
            self.size -= 1
        else:
            x.prev.next = x.next
            if x.next:
                x.next.prev = x.prev
            x.prev = x.next
            if x.next:
                x.next.next = x.prev
            x.next = None
            self.size -= 1

    def __iter__(self):
        current = self.head
        while current:
            yield current.value
            current = current.next

def process_queries(N, A, Q, queries):
    dll = DoublyLinkedList()
    for a in A:
        dll.insert_after(a, a)
    for query in queries:
        if query[0] == 1:
            x, y = query[1], query[2]
            dll.insert_after(x, y)
        elif query[0] == 2:
            x = query[1]
            dll.remove(x)
    return list(dll)

