from collections import deque

def can_reach_goal(grid, medicines):
    H = len(grid)
    W = len(grid[0])
    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                goal = (i, j)

    queue = deque([(start[0], start[1], 0)])
    visited = set()
    visited.add((start[0], start[1], 0))

    while queue:
        i, j, energy = queue.popleft()

        if (i, j) == goal:
            return "Yes"

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#':
                if (ni, nj, energy) not in visited:
                    visited.add((ni, nj, energy))
                    queue.append((ni, nj, energy))
                    if grid[ni][nj] == 'S':
                        queue.append((ni, nj, energy + 1))
                    elif grid[ni][nj] == 'T':
                        return "Yes"

    return "No"

