def find_good_sequences(L, R):
    # Calculate the length of the sequence S(L, R)
    length = R - L + 1

    # Find the largest power of 2 that divides the length
    k = length.bit_length() - 1

    # Calculate the intervals
    intervals = []
    for i in range(k):
        start = (1 << i) * L
        end = (1 << i) * (L + k - 1)
        intervals.append((start, end))

    return k, intervals

