class SuffixTree:
    def __init__(self, words):
        self.words = words
        self.root = self.build_suffix_tree()

    def build_suffix_tree(self):
        suffix_tree = {}
        for i, word in enumerate(self.words):
            node = suffix_tree
            for j, char in enumerate(word):
                if char not in node:
                    node[char] = {}
                node = node[char]
            node['$'] = i
        return suffix_tree

    def find_longest_common_suffix(self, suffix):
        node = self.root
        for char in suffix:
            if char not in node:
                return None
            node = node[char]
        return node['$']

