def count_alternating_subarrays(nums):
    n = len(nums)
    dp = [[0, 0] for _ in range(n)]

    for i in range(n):
        dp[i][0] = 1 if nums[i] == 0 else 0
        dp[i][1] = 1 if nums[i] == 1 else 0

    for i in range(1, n):
        if nums[i] == 0:
            dp[i][0] = dp[i-1][0] + dp[i-1][1]
        else:
            dp[i][1] = dp[i-1][1] + dp[i-1][0]

    return dp[n-1][0] + dp[n-1][1]

