def kthSmallestAmount(coins, k):
    heap = []
    heapq.heappush(heap, 0)

    while len(heap) < k:
        current = heapq.heappop(heap)
        for coin in coins:
            next_amount = current + coin
            heapq.heappush(heap, next_amount)

    return heapq.heappop(heap)

